revoke all on function private.valid_studio_document(jsonb) from public,anon;
grant execute on function private.valid_studio_document(jsonb) to authenticated;
alter table public.marketing_campaigns drop constraint marketing_campaigns_content_version_check;
alter table public.marketing_campaigns add constraint marketing_campaigns_content_version_check check(content_version in (1,2));
alter table public.marketing_campaigns add constraint marketing_campaigns_v2_valid check(content_version<>2 or (content->>'version'='2' and private.valid_studio_document(content) and status='draft'));
create or replace function private.campaign_audience_contacts(source_kind public.marketing_audience_source,source_id text,target_org uuid)
returns setof public.contacts language sql stable security invoker set search_path='' as $$
 select c.* from public.contacts c where c.organization_id=target_org and c.archived_at is null and public.can_view_membership(c.assigned_membership_id) and (
  (source_kind='list' and exists(select 1 from public.contact_list_memberships m join public.contact_lists l on l.id=m.list_id where m.contact_id=c.id and l.organization_id=target_org and l.public_id=source_id)) or
  (source_kind='segment' and exists(select 1 from public.contact_segments s where s.organization_id=target_org and s.public_id=source_id and public.valid_segment_criteria(s.criteria) and
   (select case when s.criteria->>'combinator'='and' then bool_and(private.segment_rule_matches(c.id,r)) else bool_or(private.segment_rule_matches(c.id,r)) end from jsonb_array_elements(s.criteria->'rules') r))))
$$;


-- Both the invoker preview and the definer confirmation now call this same
-- membership-filtered resolver. Existing send recipients are never rewritten.
create or replace function public.resolve_campaign_audience(source_kind public.marketing_audience_source, source_id text, page_limit integer default 25, page_offset integer default 0)
returns table(contact_public_id text,display_name text,primary_email text,email_status text,matching_count bigint,eligible_count bigint,unknown_count bigint,opted_out_count bigint,suppressed_count bigint,missing_email_count bigint)
language sql stable security invoker set search_path='' as $fn$
with source_org as (
 select organization_id from public.contact_lists where source_kind='list' and public_id=source_id
 union all select organization_id from public.contact_segments where source_kind='segment' and public_id=source_id
), base as (select c.* from source_org s cross join lateral private.campaign_audience_contacts(source_kind,source_id,s.organization_id) c),
counts as(select count(*) matching,count(distinct lower(btrim(primary_email))) filter(where primary_email is not null and marketing_email_status='opted-in') eligible,
count(*) filter(where marketing_email_status='unknown') unknown,count(*) filter(where marketing_email_status='opted-out') opted_out,count(*) filter(where marketing_email_status='suppressed') suppressed,count(*) filter(where primary_email is null) missing from base)
select c.public_id,btrim(c.first_name||' '||c.last_name),c.primary_email,c.marketing_email_status::text,n.matching,n.eligible,n.unknown,n.opted_out,n.suppressed,n.missing
from base c cross join counts n order by c.updated_at desc,c.id desc limit least(greatest(page_limit,1),50) offset greatest(page_offset,0);
$fn$;
revoke all on function private.campaign_audience_contacts(public.marketing_audience_source,text,uuid) from public,anon;
grant execute on function private.campaign_audience_contacts(public.marketing_audience_source,text,uuid) to authenticated;

alter table public.marketing_campaigns add constraint marketing_campaign_document_version_matches check(content->>'version'=content_version::text);
-- V2 cannot become Ready, so neither RPC nor a direct client can queue V2.
-- SQL is also the authoritative guard for all direct table and RPC writes.
create function private.guard_marketing_campaign_history() returns trigger language plpgsql set search_path='' as $fn$
begin
 if old.status in ('sending','sent') and (
 (to_jsonb(new)-'updated_at'-'status') is distinct from (to_jsonb(old)-'updated_at'-'status')
 or (old.status='sent' and new.status<>'sent') or (old.status='sending' and new.status not in ('sending','sent'))
 ) then raise exception using errcode='42501',message='Sent and sending campaign content is read-only.'; end if;
 new.updated_at:=greatest(clock_timestamp(),old.updated_at+interval '1 microsecond');
 return new;
end $fn$;
drop trigger marketing_campaigns_set_updated_at on public.marketing_campaigns;
create trigger marketing_campaigns_history_guard before update on public.marketing_campaigns for each row execute function private.guard_marketing_campaign_history();
revoke all on function private.guard_marketing_campaign_history() from public,anon,authenticated;
-- Writes must carry the previous revision through the atomic save RPC.
revoke update on public.marketing_campaigns from authenticated;
create function public.save_marketing_campaign_draft(target_organization_id uuid,target_public_id text,expected_updated_at timestamptz,payload jsonb)
returns public.marketing_campaigns language plpgsql security definer set search_path='' as $fn$
declare m uuid; c public.marketing_campaigns;
begin
 m:=public.current_active_membership_id(target_organization_id);
 if m is null then raise exception using errcode='42501',message='Campaign unavailable.'; end if;
 if payload->>'status' not in ('draft','ready') or payload->>'status' is null then raise exception using errcode='22023',message='Invalid draft status.'; end if;
 if coalesce(target_public_id,'')<>'' then
 select * into c from public.marketing_campaigns where organization_id=target_organization_id and public_id=target_public_id for update;
 if c.id is null or c.created_by_membership_id<>m or c.status in ('sent','sending') then raise exception using errcode='42501',message='Campaign is read-only or unavailable.'; end if;
 if expected_updated_at is null or c.updated_at<>expected_updated_at then raise exception using errcode='40001',message='Stale campaign revision.'; end if;
 update public.marketing_campaigns set name=payload->>'name',description=payload->>'description',subject=payload->>'subject',preview_text=payload->>'preview_text',sender_name=payload->>'sender_name',reply_to=payload->>'reply_to',audience_type=(payload->>'audience_type')::public.marketing_audience_source,audience_public_id=payload->>'audience_public_id',content_version=(payload->>'content_version')::integer,content=payload->'content',status=(payload->>'status')::public.marketing_campaign_status where id=c.id returning * into c;
 else
 insert into public.marketing_campaigns(organization_id,created_by_membership_id,name,description,subject,preview_text,sender_name,reply_to,audience_type,audience_public_id,content_version,content,status)
 values(target_organization_id,m,payload->>'name',payload->>'description',payload->>'subject',payload->>'preview_text',payload->>'sender_name',payload->>'reply_to',(payload->>'audience_type')::public.marketing_audience_source,payload->>'audience_public_id',(payload->>'content_version')::integer,payload->'content',(payload->>'status')::public.marketing_campaign_status) returning * into c;
 end if;
 return c;
end $fn$;
revoke all on function public.save_marketing_campaign_draft(uuid,text,timestamptz,jsonb) from public,anon;
grant execute on function public.save_marketing_campaign_draft(uuid,text,timestamptz,jsonb) to authenticated;
